/** Text in Zeilen umbrechen, ohne Betrag und €-Zeichen zu trennen (sonst steht „€“ allein am Zeilenanfang) */
function zeilen(doc, text, breite) {
  return doc.splitTextToSize(String(text).replace(/(\d) €/g, "$1\u00a0€"), breite);
}

/** Falz- und Lochmarken am linken Rand nach DIN 5008: zum Falten für den Fensterumschlag und zum Lochen */
function marken(doc) {
  doc.setLineWidth(0.2);
  doc.line(3, 105, 8, 105);
  doc.line(3, 148.5, 6, 148.5);
  doc.line(3, 210, 8, 210);
}

/** „Seite 1 von 2“ unten rechts, aber nur bei mehrseitigen Briefen */
function seitenzahlen(doc) {
  const n = doc.getNumberOfPages();
  if (n < 2) return;
  for (let i = 1; i <= n; i++) {
    doc.setPage(i);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.text(`Seite ${i} von ${n}`, 190, 290, { align: "right" });
  }
}

/** PDF-Quittung für die Verhinderungspflege durch Privatpersonen. */
export async function makeQuittung() {
  const doc = await newDoc();
  if (!doc) return;
  const v = Z.S.vhp,
    c = vhpCalc(),
    a = v.ersatz === "angehoerig";
  const L0 = 25,
    W = 160;
  let y = 30;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(15);
  doc.text(a ? "Bestätigung über Ersatzpflege" : "Quittung über Ersatzpflege", L0, y);
  y += 6;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  doc.text("Verhinderungspflege nach § 39 SGB XI", L0, y);
  y += 12;
  doc.setFontSize(11);
  const rows = [
    [
      "Pflegebedürftige Person",
      `${Z.S.person.name || ""}${Z.S.person.geb ? ", geb. " + datumBrief(Z.S.person.geb) : ""}`,
    ],
    ["Versichertennummer", Z.S.person.vnr || ""],
    ["Hauptpflegeperson (verhindert)", v.haupt || ""],
    ["Grund", VHP_GRUND[v.grund] || ""],
    ["Zeitraum", vhpZeitraum().replace(/^vom |^am /, "")],
    ["Art", v.art === "stunden" ? "stundenweise (unter 8 Std./Tag)" : "ganztägig"],
    ["Ersatzpflegeperson", v.eName || ""],
    ["Anschrift", v.eAdresse || ""],
  ];
  if (a) rows.push(["Verwandtschaftsverhältnis", v.eBez || ""]);
  rows.push(
    ["Geleistete Stunden", numDE(v.stunden) ? String(numDE(v.stunden)) : ""],
    ["Stundensatz", numDE(v.satz) ? eur(numDE(v.satz), 2) : ""],
  );
  if (c.fahrt) rows.push(["Fahrtkosten", `${numDE(v.km)} km × ${eur(KM_SATZ, 2)} = ${eur(c.fahrt, 2)}`]);
  for (const [k, val] of rows) {
    doc.setFont("helvetica", "bold");
    doc.text(k + ":", L0, y);
    doc.setFont("helvetica", "normal");
    doc.text(val || "________________________________", L0 + 62, y);
    y += 8;
  }
  y += 4;
  const sum = (c.basis || 0) + (c.fahrt || 0);
  const txt = a
    ? `Ich bestätige, dass ich die Pflege in dem genannten Zeitraum übernommen habe.${sum ? ` Dafür sind mir Aufwendungen in Höhe von ${eur(sum, 2)} entstanden.` : ""}`
    : `Ich bestätige, dass ich die Pflege in dem genannten Zeitraum übernommen und dafür ${sum ? eur(sum, 2) : "________ €"} erhalten habe.`;
  doc.text(zeilen(doc, txt, W), L0, y);
  y += 24;
  doc.line(L0, y, L0 + 60, y);
  doc.line(L0 + 80, y, L0 + 160, y);
  doc.setFontSize(8);
  doc.text("Ort, Datum", L0, y + 4);
  doc.text("Unterschrift Ersatzpflegeperson", L0 + 80, y + 4);
  y += 22;
  doc.setFontSize(9);
  doc.setTextColor(90);
  doc.text(
    doc.splitTextToSize(
      "Bei Fahrtkosten bitte eine Aufstellung beilegen (Datum, Strecke, Kilometer). Bei Verdienstausfall eine Bescheinigung des Arbeitgebers.",
      W,
    ),
    L0,
    y,
  );
  await saveFile(
    a ? "Bestaetigung-Ersatzpflege.pdf" : "Quittung-Ersatzpflege.pdf",
    doc.output("blob"),
    "PDF gespeichert",
  );
}

function drawLetter(doc, b, L = curLetter(b), docs = docsFor(b)) {
  const p = Z.S.person,
    a = Z.S.rolle === "angehoerig",
    r = RECIP[b.to]();
  const L0 = 25,
    W = 165;
  let y;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  const abs =
    [a ? p.absender : p.name, a ? p.absStrasse : p.strasse, a ? p.absOrt : p.ort].filter(Boolean).join(" · ") ||
    "[Absender]";
  marken(doc);
  // DIN 5008 Form B: Rücksendeangabe 45–50 mm, Anschrift ab 62,7 mm von oben (passt ins Fenster eines DL-Umschlags)
  doc.text(abs, L0, 49);
  doc.setFontSize(11);
  const ea = empfAdresse(b.to);
  doc.text([r.name, ea.strasse || "[Straße / Postfach]", ea.ort || "[PLZ Ort]"], L0, 66);
  const ortName = ((a ? p.absOrt : p.ort) || "").replace(/^\d{5}\s*/, "");
  doc.text(`${ortName ? ortName + ", " : ""}${today()}`, 190, 95, { align: "right" });
  doc.setFont("helvetica", "bold");
  y = 105;
  const subl = doc.splitTextToSize(L.subject, W);
  doc.text(subl, L0, y);
  y += subl.length * 5.5 + 6;
  doc.setFont("helvetica", "normal");
  const zl = zeilen(doc, L.body, W);
  // Grußformel, Name und Kontakt bleiben mit der Unterschrift zusammen auf einer Seite
  const gruss = zl.findIndex((z) => /^Mit freundlichen Grüßen/.test(z));
  for (let i = 0; i < zl.length; i++) {
    const rest = i === gruss ? (zl.length - i) * 5.2 + 14 : 0;
    if (y > 275 || (rest && y + rest > 280)) {
      doc.addPage();
      y = 20;
    }
    doc.text(zl[i], L0, y);
    y += 5.2;
  }
  y += 10;
  if (y > 270) {
    doc.addPage();
    y = 20;
  }
  doc.line(L0, y, L0 + 70, y);
  doc.setFontSize(8);
  doc.text("Unterschrift", L0, y + 4);
  if (docs.length) {
    y += 14;
    if (y > 260) {
      doc.addPage();
      y = 20;
    }
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text("Anlagen", L0, y);
    doc.setFont("helvetica", "normal");
    y += 5;
    for (const d of docs) {
      if (y > 282) {
        doc.addPage();
        y = 20;
      }
      doc.text("– " + d, L0, y);
      y += 5;
    }
  }
}

/**
 * Folgebrief zu einem Antrag (Nachfrage oder Widerspruch) als PDF im selben Briefformat.
 * @param b Leistung (für Empfänger und Absender)
 * @param L Betreff und Text
 * @param datei Dateiname
 * @param anlagen Liste der Anlagen
 */
export async function makeBrief(b, L, datei, anlagen = []) {
  const doc = await newDoc();
  if (!doc) return;
  drawLetter(doc, b, L, anlagen);
  seitenzahlen(doc);
  await saveFile(datei, doc.output("blob"), "PDF gespeichert");
}

/**
 * Vorbereitung auf den Termin mit dem Medizinischen Dienst als PDF: Unterlagen, Tipps und, wenn der Pflegegrad-Rechner
 * ausgefüllt ist, die Punkte mit Hilfebedarf nach Bereichen. Freie Zeilen für eigene Notizen.
 * @param antworten Antworten des Pflegegrad-Rechners
 */
export async function makeGutachterBlatt(antworten) {
  const doc = await newDoc();
  if (!doc) return;
  const g = gutachterBlatt(antworten || []),
    p = Z.S.person,
    L0 = 25,
    W = 160;
  let y = 28;
  const platz = (h) => {
    if (y + h > 280) {
      doc.addPage();
      y = 22;
    }
  };
  const ueberschrift = (t) => {
    platz(16);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text(t, L0, y);
    y += 7;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10.5);
  };
  const punkt = (t, zeichen = "–") => {
    const z = zeilen(doc, t, W - 7);
    platz(z.length * 4.8);
    doc.text(zeichen, L0, y);
    doc.text(z, L0 + 6, y);
    y += z.length * 4.8 + 1.5;
  };
  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  doc.text("Vorbereitung auf den Gutachter-Termin", L0, y);
  y += 6;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  doc.text(`Medizinischer Dienst${p.name ? " – für " + p.name : ""}`, L0, y);
  y += 12;
  ueberschrift("Bereitlegen");
  for (const u of g.unterlagen) punkt(u, "[  ]");
  y += 4;
  ueberschrift("Beim Termin");
  for (const t of g.tipps) punkt(t);
  y += 4;
  if (g.bereiche.length) {
    ueberschrift("Hier wird Hilfe gebraucht (aus dem Pflegegrad-Rechner)");
    for (const b of g.bereiche) {
      platz(12);
      doc.setFont("helvetica", "bold");
      doc.text(b.titel, L0, y);
      doc.setFont("helvetica", "normal");
      y += 5.5;
      for (const [frage, antwort] of b.punkte) punkt(`${frage}${frage.endsWith("?") ? "" : ":"} ${antwort}`);
      y += 2;
    }
  } else {
    ueberschrift("Wo wird Hilfe gebraucht?");
    punkt(
      "Tipp: Mit dem Pflegegrad-Rechner in der App ausfüllen, dann stehen deine Antworten hier nach Bereichen geordnet.",
    );
  }
  y += 4;
  ueberschrift("Eigene Notizen");
  for (let i = 0; i < 6; i++) {
    platz(9);
    y += 7;
    doc.setDrawColor(190);
    doc.line(L0, y, L0 + W, y);
  }
  seitenzahlen(doc);
  await saveFile("Vorbereitung-Gutachter.pdf", doc.output("blob"), "PDF gespeichert");
}

/** Vollmacht für Angehörige als PDF zum Ausdrucken und Unterschreiben. */
export async function makeVollmacht() {
  const doc = await newDoc();
  if (!doc) return;
  const v = vollmachtInhalt(),
    L0 = 25,
    W = 160,
    LEER = "________________________________________";
  let y = 30;
  const absatz = (text, abstand = 8) => {
    const z = zeilen(doc, text, W);
    doc.text(z, L0, y);
    y += z.length * 5.2 + abstand;
  };
  const felder = (liste) => {
    for (const [k, val] of liste) {
      doc.setFont("helvetica", "bold");
      doc.text(k + ":", L0, y);
      doc.setFont("helvetica", "normal");
      doc.text(val || LEER, L0 + 45, y);
      y += 7;
    }
    y += 3;
  };
  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  doc.text("Vollmacht", L0, y);
  y += 6;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  doc.text("für Angelegenheiten bei Kranken- und Pflegekasse und bei Behörden", L0, y);
  y += 12;
  doc.setFontSize(11);
  absatz("Ich,", 2);
  felder(v.geber);
  absatz("bevollmächtige hiermit", 2);
  felder(v.nehmer);
  absatz(v.umfang, 1);
  for (const pkt of v.punkte) absatz("–  " + pkt, 0);
  y += 6;
  absatz(v.daten);
  absatz(v.dauer, 22);
  doc.line(L0, y, L0 + 70, y);
  doc.line(L0 + 90, y, L0 + 160, y);
  doc.setFontSize(8);
  doc.text("Ort, Datum", L0, y + 4);
  doc.text("Unterschrift der Person, die die Vollmacht gibt", L0 + 90, y + 4);
  y += 20;
  doc.line(L0 + 90, y, L0 + 160, y);
  doc.text("Unterschrift der bevollmächtigten Person", L0 + 90, y + 4);
  y += 16;
  doc.setFontSize(9);
  doc.setTextColor(90);
  doc.text(doc.splitTextToSize(v.hinweis, W), L0, y);
  await saveFile("Vollmacht.pdf", doc.output("blob"), "PDF gespeichert");
}

/**
 * Antrag als PDF-Brief.
 * @param b Leistung
 */
export async function makePDF(b) {
  const doc = await newDoc();
  if (!doc) return;
  drawLetter(doc, b);
  seitenzahlen(doc);
  await saveFile(`Antrag-${b.k}.pdf`, doc.output("blob"), "PDF gespeichert");
}

async function blobToDataURL(id) {
  const res = await fetch(blobUrl(id));
  if (!res.ok) throw new Error("fetch");
  const bl = await res.blob();
  if (!/^image\//.test(bl.type)) return null;
  const bmp = await createImageBitmap(bl);
  const c = document.createElement("canvas");
  const s = Math.min(1, 1600 / Math.max(bmp.width, bmp.height));
  c.width = Math.round(bmp.width * s);
  c.height = Math.round(bmp.height * s);
  c.getContext("2d").drawImage(bmp, 0, 0, c.width, c.height);
  return { url: c.toDataURL("image/jpeg", 0.8), w: c.width, h: c.height };
}

/**
 * Belegmappe als PDF: Übersicht und Fotos, auf Wunsch mit Antrag und nur Zuzahlungen.
 * @param withLetter mit Antrag
 * @param onlyZZ nur Zuzahlungen
 * @param yearsArg Jahre
 */
export async function makeMappe(withLetter, onlyZZ, yearsArg) {
  const doc = await newDoc();
  if (!doc) return;
  toast("PDF wird erstellt …");
  const years = yearsArg || selYears();
  const kf = Z.S.belegFilter.kat || "";
  const jahr = years.length === 1 ? years[0] : years.slice().reverse().join("-");
  let list = Z.BEL.filter((b) => years.includes(String(b.jahr)));
  if (onlyZZ) list = list.filter((b) => KATS[b.kat] && KATS[b.kat].zz);
  else if (kf) list = list.filter((b) => b.kat === kf);
  list.sort((a, b) => (a.kat + a.datum).localeCompare(b.kat + b.datum));
  if (withLetter) {
    Z.befJahr = years[0];
    drawLetter(
      doc,
      B.find((x) => x.k === "befreiung"),
    );
    doc.addPage();
  }
  const L0 = 20;
  let y = 22;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(15);
  doc.text(`Belegübersicht ${jahr.replace("-", " – ")}`, L0, y);
  y += 7;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.text(
    [Z.S.person.name || "", Z.S.person.vnr ? `Versichertennummer ${Z.S.person.vnr}` : "", kasseName()]
      .filter(Boolean)
      .join(" · "),
    L0,
    y,
  );
  y += 10;
  doc.setFont("helvetica", "bold");
  doc.text("Nr.", L0, y);
  doc.text("Datum", L0 + 12, y);
  doc.text("Art / Beschreibung", L0 + 36, y);
  doc.text("Betrag", 190, y, { align: "right" });
  y += 2;
  doc.line(L0, y, 190, y);
  y += 5;
  doc.setFont("helvetica", "normal");
  let sum = 0;
  list.forEach((b, i) => {
    if (y > 280) {
      doc.addPage();
      y = 20;
    }
    const d = parseIso(b.datum);
    const t = `${(KATS[b.kat] || KATS.sonst).t}${b.titel ? " – " + b.titel : ""}${b.asset && !/^image\//.test(b.ctype || "") ? " (PDF separat)" : ""}`;
    doc.text(String(i + 1), L0, y);
    doc.text(d ? deD(d) : "–", L0 + 12, y);
    doc.text(doc.splitTextToSize(t, 110)[0], L0 + 36, y);
    doc.text(b.betrag !== "" && b.betrag != null ? eur(Number(b.betrag), 2) : "–", 190, y, { align: "right" });
    sum += Number(b.betrag) || 0;
    y += 6;
  });
  doc.line(L0, y - 2, 190, y - 2);
  doc.setFont("helvetica", "bold");
  doc.text("Summe", L0 + 36, y + 3);
  doc.text(eur(sum, 2), 190, y + 3, { align: "right" });
  let i = 0;
  for (const b of list) {
    i++;
    if (!b.asset || !/^image\//.test(b.ctype || "")) continue;
    try {
      const im = await blobToDataURL(b.asset);
      if (!im) continue;
      doc.addPage();
      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      const d = parseIso(b.datum);
      doc.text(
        `Beleg ${i}: ${(KATS[b.kat] || KATS.sonst).t}${d ? " · " + deD(d) : ""}${b.betrag ? " · " + eur(Number(b.betrag), 2) : ""}`,
        20,
        15,
      );
      const maxW = 170,
        maxH = 260;
      const s = Math.min(maxW / im.w, maxH / im.h);
      doc.addImage(im.url, "JPEG", 20, 22, im.w * s, im.h * s);
    } catch (e) {}
  }
  await saveFile(
    withLetter ? `Befreiungsantrag-${jahr}.pdf` : `Belegmappe-${jahr}.pdf`,
    doc.output("blob"),
    "PDF gespeichert",
  );
}

/** Belege der gewählten Jahre als Tabelle (CSV, mit Semikolon für Excel). */
export async function makeCSV() {
  const years = selYears();
  const jahr = years.slice().reverse().join("-");
  const rows = [["Datum", "Art", "Beschreibung", "Betrag", "Eingereicht"]];
  Z.BEL.filter((b) => years.includes(String(b.jahr)) && (!Z.S.belegFilter.kat || b.kat === Z.S.belegFilter.kat))
    .sort((a, b) => (a.datum || "").localeCompare(b.datum || ""))
    .forEach((b) =>
      rows.push([
        b.datum ? deD(parseIso(b.datum)) : "",
        (KATS[b.kat] || KATS.sonst).t,
        b.titel || "",
        b.betrag != null && b.betrag !== "" ? Number(b.betrag).toFixed(2).replace(".", ",") : "",
        b.eingereicht ? "ja" : "nein",
      ]),
    );
  const csv = "﻿" + rows.map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(";")).join("\r\n");
  await saveFile(`Belege-${jahr}.csv`, csv, "Tabelle gespeichert");
}
